namespace HarborValeGreybox.Racing {
public sealed class GarageInventoryView:IDisposable {
 readonly ExpandedWorkshop shop;RaceProgressStore Store=>shop.Store;string focus,dragEngine,dragDonor,pendingEngine,pendingDonor,pendingReceiver,message;int pendingFee;Vector2 carScroll,inventoryScroll;GameObject preview;Camera camera;RenderTexture texture;string previewModel;float lastRender=-1;struct Handle{public Rect rect;public string engine,donor;}readonly System.Collections.Generic.List<Handle> handles=new System.Collections.Generic.List<Handle>();
 public string FocusedCar=>focus;public string Message=>message;public bool HasPendingDrop=>pendingReceiver!=null;
 public GarageInventoryView(ExpandedWorkshop owner){shop=owner;}
 public void Open(){focus=Store.Profile.fleet.cars.FirstOrDefault(c=>c.id==Store.Profile.fleet.selectedId&&c.owner=="player")?.id??Store.Profile.fleet.cars.FirstOrDefault(c=>c.owner=="player")?.id;pendingReceiver=dragEngine=dragDonor=null;message=null;}
 static string ModelName(string model)=>model=="car_finch"?"Aster Finch":VehicleLineup.Find(model).name;
 public void Focus(string id){if(FleetLedger.Find(Store.Profile.fleet,id).owner!="player")throw new InvalidOperationException("Car not owned");focus=id;}
 public void BeginDragEngine(string engine,string donor=null){var unit=EngineInventoryLedger.Find(Store.Profile.fleet,engine);if(unit.owner!="player")throw new InvalidOperationException("Engine not owned");dragEngine=engine;dragDonor=donor;message=null;}
 public bool DropOnCar(string receiver){if(dragEngine==null)return false;try{pendingFee=dragDonor==null?Store.EngineFitFee(dragEngine,receiver):Store.EngineTransferFee(dragDonor,receiver);pendingReceiver=receiver;pendingEngine=dragEngine;pendingDonor=dragDonor;message="Review mounting/ECU labor, then confirm the engine move.";dragEngine=dragDonor=null;return true;}catch(Exception e){message=e.Message;dragEngine=dragDonor=null;return false;}}
 public bool DropInStorage(){if(dragEngine==null||dragDonor==null){dragEngine=dragDonor=null;return false;}try{Store.PullEngine(Guid.NewGuid().ToString("N"),dragDonor);shop.RefreshOwnedVehicle();message="Engine removed to storage. Its installed engine upgrades stay with the assembly.";dragEngine=dragDonor=null;return true;}catch(Exception e){message=e.Message;dragEngine=dragDonor=null;return false;}}
 public bool ConfirmMove(){if(pendingReceiver==null)return false;try{if(pendingDonor==null)Store.FitEngine(Guid.NewGuid().ToString("N"),pendingEngine,pendingReceiver,pendingFee);else Store.TransferEngine(Guid.NewGuid().ToString("N"),pendingDonor,pendingReceiver,pendingFee);focus=pendingReceiver;shop.RefreshOwnedVehicle();pendingReceiver=null;message="Engine fitted and labor saved. Displaced engine moved to storage; donor car keeps its chassis upgrades.";return true;}catch(Exception e){message=e.Message;return false;}}
 public bool DriveFocused(){try{if(focus==null||!Store.HasEngine(focus))throw new InvalidOperationException("Fit an engine before selecting this car for driving");Store.SelectVehicle(Guid.NewGuid().ToString("N"),focus);shop.RefreshOwnedVehicle();message="Driving car selected.";return true;}catch(Exception e){message=e.Message;return false;}}
 GUIStyle Text(int size=17,bool bold=false){var s=new GUIStyle(GUI.skin.label){fontSize=size,wordWrap=true,fontStyle=bold?FontStyle.Bold:FontStyle.Normal};s.normal.textColor=Color.white;return s;}
 static void Fill(Rect r,Color c){var before=GUI.color;GUI.color=c;GUI.DrawTexture(r,Texture2D.whiteTexture);GUI.color=before;}
 void Label(Rect r,string t,int size=17,bool bold=false)=>GUI.Label(r,t,Text(size,bold));
 void EngineLabel(Rect rect,string id,string donor){var e=EngineInventoryLedger.Find(Store.Profile.fleet,id);Fill(rect,new Color(.12f,.26f,.29f));Label(rect,"DRAG  "+ModelName(e.modelId),14,true);}

 void CarPreview(Rect rect,string id){if(previewModel!=id||preview==null){ReleasePreview();preview=UnityEngine.Object.Instantiate(Resources.Load<GameObject>(id=="car_finch"?"RivalsFinch":id));preview.name="Inventory garage car preview / no physics";preview.transform.position=new Vector3(-300,-1500,0);foreach(var collider in preview.GetComponentsInChildren<Collider>()){collider.enabled=false;UnityEngine.Object.Destroy(collider);}foreach(var script in preview.GetComponentsInChildren<MonoBehaviour>())UnityEngine.Object.Destroy(script);foreach(var t in preview.GetComponentsInChildren<Transform>())t.gameObject.layer=31;camera=new GameObject("Inventory preview camera").AddComponent<Camera>();camera.transform.SetParent(preview.transform,false);camera.enabled=false;camera.fieldOfView=32;camera.cullingMask=1<<31;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.035f,.06f,.085f);camera.farClipPlane=25;texture=new RenderTexture(600,360,16);texture.Create();camera.targetTexture=texture;var light=new GameObject("Inventory preview fill").AddComponent<Light>();light.transform.SetParent(preview.transform,false);light.transform.localPosition=new Vector3(2,4,3);light.type=LightType.Point;light.range=12;light.intensity=2;light.cullingMask=1<<31;previewModel=id;lastRender=-1;}if(Event.current.type==EventType.Repaint&&Time.unscaledTime-lastRender>.04f){lastRender=Time.unscaledTime;camera.transform.position=preview.transform.position+Quaternion.Euler(0,30+Time.unscaledTime*6,0)*new Vector3(0,1.9f,6.1f);camera.transform.LookAt(preview.transform.position+Vector3.up*.65f);camera.Render();}GUI.DrawTexture(rect,texture,ScaleMode.ScaleToFit,false);}
 public void Draw(){handles.Clear();GUI.depth=-1200;var matrix=GUI.matrix;GUI.matrix=Matrix4x4.Scale(new Vector3(Screen.width/1440f,Screen.height/900f,1));var bg=GUI.backgroundColor;Fill(new Rect(0,0,1440,900),new Color(.035f,.06f,.085f));var button=new GUIStyle(GUI.skin.button){fontSize=18,wordWrap=true};button.normal.background=button.hover.background=button.active.background=Texture2D.whiteTexture;button.normal.textColor=button.hover.textColor=button.active.textColor=Color.white;GUI.backgroundColor=new Color(.11f,.22f,.27f);Label(new Rect(30,24,1050,44),"HARBOR VALE / YOUR GARAGE",30,true);Label(new Rect(1130,32,280,34),Store.Profile.availableCredits.ToString("N0")+" cr",24,true);Label(new Rect(30,78,1380,42),"Drag an installed engine to storage, or drag an engine onto another owned car. Mounts, ECU, compatibility and supporting hardware are checked before fitting.",18);
  Fill(new Rect(24,140,548,636),new Color(.065f,.105f,.13f));Label(new Rect(40,153,510,28),"YOUR CARS  /  chassis and upgrades stay saved",18,true);var cars=Store.Profile.fleet.cars.Where(c=>c.owner=="player").ToArray();var cardRects=new System.Collections.Generic.List<System.Collections.Generic.KeyValuePair<string,Rect>>();carScroll=GUI.BeginScrollView(new Rect(34,193,528,570),carScroll,new Rect(0,0,503,Mathf.Max(560,Mathf.Ceil(cars.Length/2f)*155)));for(int i=0;i<cars.Length;i++){var c=cars[i];var r=new Rect(i%2*252,i/2*155,240,144);Fill(r,c.id==focus?new Color(.11f,.27f,.29f):new Color(.09f,.15f,.19f));if(GUI.Button(new Rect(r.x+8,r.y+5,224,64),ModelName(VehicleLineup.Model(c))+(c.id==Store.Profile.fleet.selectedId?"\nDRIVING":""),button))Focus(c.id);bool engine=Store.HasEngine(c.id);Label(new Rect(r.x+8,r.y+74,224,22),engine?"Engine fitted · "+EngineInventoryLedger.Find(Store.Profile.fleet,c.engineId).modelId.Replace("car_","").ToUpperInvariant():"ENGINE BAY EMPTY",14);if(engine){EngineLabel(new Rect(r.x+8,r.y+103,224,32),c.engineId,c.id);handles.Add(new Handle{rect=new Rect(42+r.x-carScroll.x,296+r.y-carScroll.y,224,32),engine=c.engineId,donor=c.id});}cardRects.Add(new System.Collections.Generic.KeyValuePair<string,Rect>(c.id,new Rect(34+r.x-carScroll.x,193+r.y-carScroll.y,r.width,r.height)));}GUI.EndScrollView();if(cars.Length==0)Label(new Rect(44,220,500,150),"No owned cars. The free recovery loaner can earn cash for a replacement. Stored engines remain yours.",20);
  Fill(new Rect(590,140,390,636),new Color(.065f,.105f,.13f));if(focus!=null){var c=FleetLedger.Find(Store.Profile.fleet,focus);Label(new Rect(609,158,350,50),ModelName(VehicleLineup.Model(c)),24,true);CarPreview(new Rect(601,215,366,210),VehicleLineup.Model(c));bool engine=Store.HasEngine(c.id);if(engine){var data=WorkshopCatalog.ForBuild(VehicleLineup.Model(c),c.build).Resolve(c.build);Label(new Rect(609,435,350,86),ChassisTuning.CrankHp(data).ToString("F0")+" HP / "+ChassisTuning.EstimatedWhp(data).ToString("F0")+" WHP est\n"+data.massKg.ToString("N0")+" kg · "+FitmentTuning.Drive(WorkshopCatalog.Load(VehicleLineup.Model(c)),c.build).ToUpperInvariant(),21,true);EngineLabel(new Rect(607,535,356,40),c.engineId,c.id);handles.Add(new Handle{rect=new Rect(607,535,356,40),engine=c.engineId,donor=c.id});}else Label(new Rect(608,440,355,100),"ENGINE REMOVED\nDrag a compatible assembly here. This car cannot race or drive until fitted.",22,true);Label(new Rect(609,591,350,93),"Chassis: gearbox S"+c.build.gearboxStage+" · brakes S"+c.build.brakeStage+"\nTires S"+c.build.tireStage+" · suspension S"+c.build.suspensionStage+"\nPrepare supporting hardware before removing the engine.",17);GUI.enabled=engine;if(GUI.Button(new Rect(607,691,170,48),"Select to drive",button))DriveFocused();if(GUI.Button(new Rect(787,691,176,48),"Upgrade parts",button)){if(DriveFocused())shop.OpenUpgradeMode();}GUI.enabled=true;cardRects.Add(new System.Collections.Generic.KeyValuePair<string,Rect>(c.id,new Rect(590,208,390,375)));}
  var storage=new Rect(998,140,416,636);Fill(storage,new Color(.065f,.105f,.13f));Label(new Rect(1015,155,380,44),"INVENTORY / ENGINE ASSEMBLIES",19,true);Label(new Rect(1015,202,380,70),"Engines keep their installed tune, turbo, intercooler, intake and exhaust hardware. Empty donor chassis remain owned.",16);var stored=Store.Profile.fleet.engines.Where(e=>e.owner=="player"&&string.IsNullOrEmpty(e.installedCarId)).ToArray();inventoryScroll=GUI.BeginScrollView(new Rect(1008,282,396,477),inventoryScroll,new Rect(0,0,374,Mathf.Max(450,stored.Length*112)));for(int i=0;i<stored.Length;i++){var e=stored[i];EngineLabel(new Rect(5,i*112+5,361,38),e.id,null);handles.Add(new Handle{rect=new Rect(1013,287+i*112-inventoryScroll.y,361,38),engine=e.id,donor=null});Label(new Rect(10,i*112+47,352,58),"NA/tune S"+e.build.naStage+" · "+e.build.induction.ToUpperInvariant()+" S"+e.build.inductionStage+"\nCooling S"+e.build.coolingStage+" · intake S"+e.build.intakeStage+" · exhaust S"+e.build.exhaustStage,15);}GUI.EndScrollView();if(stored.Length==0)Label(new Rect(1018,325,375,160),"No stored engines yet.\n\nDrag a car's engine handle into this area to remove it, or directly onto another car for a complete transfer.",19);
  var ev=Event.current;var mouse=ev.mousePosition;if(ev.type==EventType.MouseDown&&ev.button==0&&pendingReceiver==null){foreach(var handle in handles)if(handle.rect.Contains(mouse)&&mouse.y>=193&&mouse.y<760){BeginDragEngine(handle.engine,handle.donor);GUIUtility.hotControl=GUIUtility.GetControlID(FocusType.Passive);ev.Use();break;}}if(dragEngine!=null){if(ev.type==EventType.MouseUp&&ev.button==0){GUIUtility.hotControl=0;var target=cardRects.FirstOrDefault(p=>p.Value.Contains(mouse));if(target.Key!=null)DropOnCar(target.Key);else if(storage.Contains(mouse))DropInStorage();else dragEngine=dragDonor=null;ev.Use();}else{Fill(new Rect(mouse.x+12,mouse.y+12,310,58),new Color(.08f,.52f,.46f));Label(new Rect(mouse.x+22,mouse.y+20,290,46),"ENGINE ASSEMBLY\nDrop onto a car or inventory",17,true);if(ev.type==EventType.MouseDrag)ev.Use();}}
  Label(new Rect(30,790,1380,49),message??"Whole engine assemblies move once, never duplicate. Fitted chassis hardware stays with its car. Missing engines disable driving; the recovery loaner remains available.",17);if(GUI.Button(new Rect(30,845,460,38),"Buy another car",button)){shop.Close();var director=RivalRaceDirector.Instance;if(director.OpenPanel())director.OpenShowroom();}if(GUI.Button(new Rect(510,845,904,38),"Return to driving / G",button))shop.Close();
  if(pendingReceiver!=null){Fill(new Rect(0,0,1440,900),new Color(0,0,0,.75f));Fill(new Rect(365,265,710,350),new Color(.08f,.15f,.19f));Label(new Rect(393,286,650,44),"CONFIRM ENGINE INSTALLATION",25,true);Label(new Rect(393,346,650,135),"Fit "+ModelName(EngineInventoryLedger.Find(Store.Profile.fleet,pendingEngine).modelId)+" engine into "+ModelName(VehicleLineup.Model(FleetLedger.Find(Store.Profile.fleet,pendingReceiver)))+"?\n\nMounts, ECU and labor: "+pendingFee.ToString("N0")+" cr. The displaced engine goes to inventory; the donor chassis keeps its own suspension, brakes, gearbox and tires.",20);if(GUI.Button(new Rect(393,535,310,48),"Fit engine · "+pendingFee.ToString("N0")+" cr",button))ConfirmMove();if(GUI.Button(new Rect(727,535,310,48),"Cancel",button))pendingReceiver=null;}
  GUI.backgroundColor=bg;GUI.matrix=matrix;
 }
 static Vector2 Pointer(){
#if ENABLE_INPUT_SYSTEM
 var m=UnityEngine.InputSystem.Mouse.current;if(m==null)return Vector2.zero;var p=m.position.ReadValue();
#else
 Vector2 p=Input.mousePosition;
#endif
 return new Vector2(p.x*1440/Screen.width,(Screen.height-p.y)*900/Screen.height);}
 void ReleasePreview(){if(camera!=null)camera.targetTexture=null;if(preview!=null)UnityEngine.Object.Destroy(preview);if(texture!=null){texture.Release();UnityEngine.Object.Destroy(texture);}preview=null;camera=null;texture=null;previewModel=null;}
 public void Dispose(){ReleasePreview();dragEngine=pendingReceiver=null;}
}
